from pathlib import Path
from shutil import copy2
from openpyxl import load_workbook

FILE = Path("order_summary.xlsx")
ORDER_ID = "ORD-6C71B1"
NEW_STATUS = "confirmed"

# Create a backup before modifying the workbook.
copy2(FILE, FILE.with_name("order_summary.backup.xlsx"))

workbook = load_workbook(FILE)
matches = []

for worksheet in workbook.worksheets:
    rows = list(worksheet.iter_rows())

    # Locate the Order ID and Status columns from a header row.
    for header_index, row in enumerate(rows):
        headers = {
            str(cell.value).strip().lower(): column_index
            for column_index, cell in enumerate(row)
            if cell.value is not None
        }

        order_column = next(
            (index for name, index in headers.items()
             if name in {"order id", "order_id", "order number", "order"}),
            None,
        )
        status_column = next(
            (index for name, index in headers.items() if name == "status"),
            None,
        )

        if order_column is None or status_column is None:
            continue

        for data_row in rows[header_index + 1:]:
            order_value = data_row[order_column].value
            if str(order_value).strip().upper() == ORDER_ID.upper():
                old_status = data_row[status_column].value

                if str(old_status).strip().lower() != "cancelled":
                    raise RuntimeError(
                        f"{ORDER_ID} was found in sheet '{worksheet.title}', "
                        f"but its status is {old_status!r}, not 'cancelled'."
                    )

                data_row[status_column].value = NEW_STATUS
                matches.append((worksheet.title, data_row[status_column].row))

        break

if not matches:
    raise RuntimeError(f"Order {ORDER_ID} was not found.")

if len(matches) > 1:
    raise RuntimeError(
        f"Order {ORDER_ID} appears {len(matches)} times; no file was saved."
    )

workbook.save(FILE)
workbook.close()

sheet, row = matches[0]
print(
    f"Updated {ORDER_ID} from cancelled to confirmed "
    f"in sheet '{sheet}', row {row}."
)
print("Backup: order_summary.backup.xlsx")
